def update_exams():
    with open(exams_file, 'r', encoding='utf-8') as f:
        exams_data = json.load(f)
    
    found = False
    for exam in exams_data:
        if exam['id'] == 'exam-32':
            found = True
            exam['sections']['A']['questions'] = section_A_questions
            exam['sections']['B']['questions'] = section_B_questions
            print("Updated existing exam-32 successfully!")
            break
            
    if not found:
        new_exam = {
          "id": "exam-32",
          "title": "📚 [제 32 회차] 2027 통합 모의고사 (교육학+전공)",
          "sections": {
            "P": exams_data[0]['sections']['P'],
            "A": {
              "title": "전문상담 [전공 A]",
              "timeLimit": 60,
              "questions": section_A_questions
            },
            "B": {
              "title": "전문상담 [전공 B]",
              "timeLimit": 60,
              "questions": section_B_questions
            }
          }
        }
        exams_data.append(new_exam)
        print("Created and appended new exam-32!")

    with open(exams_file, 'w', encoding='utf-8') as f:
        json.dump(exams_data, f, ensure_ascii=False, indent=2)

    with open(default_file, 'w', encoding='utf-8') as f:
        json.dump(exams_data, f, ensure_ascii=False, indent=2)

update_exams()
